const test = require('node:test');
const assert = require('node:assert/strict');
const app = require('../method_router.cjs');
test('method tokens keep their case', () => {
  const routes=JSON.parse('{"GET":"list","get":"legacy","Ship":"dispatch","SHIP":"bulk"}');
  for (const [m,w] of [['GET','list'],['get','legacy'],['Get',null],['Ship','dispatch'],['SHIP','bulk'],['ship',null],['toString',null]]) assert.equal(app.lookup(routes,m),w);
  assert.equal(app.lookup({GET:0},'GET'),0);
});
